#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define F first
#define S second
#define mp make_pair
#define pii pair<int,int>
#define vi vector<int>
#define pq priority_queue
#define pb push_back
#define watch(x) cout << (#x) << " is " << (x) << endl
#define ALL(a) (a.begin()),(a.end())
#define FOR(x,to) for(ll x=0;x<(to);x++)
#define FORR(x,to) for(ll x=1;x<=(to);x++)
#define fastio ios::sync_with_stdio(0); cin.tie(NULL);
const int INF = 0x3f3f3f3f;
const int MOD = 1e9+7;

ll modExponentiation(ll base, ll exp){
    ll result = 1;
    while(exp > 0){
        if(exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll p, k;
    cin >> p >> k;

    if(k == 0){
        cout << modExponentiation(p, p-1) << "\n";
    } else if(k == 1){
        cout << modExponentiation(p, p) << "\n";
    } else {
        ll cycle = k;
        ll count = 1;
        while(cycle != 1){
            cycle = (cycle * k) % p;
            count++;
        }
        ll exp = (p - 1) / count;
        cout << modExponentiation(p, exp) << "\n";
    }
}
